describe('No results found message - API empty list handling', () => {
  const apiUrl = 'https://api.example.com/search';
  const searchEndpoint = '/api/search';

  beforeEach(() => {
    cy.visit('/search');
  });

  it('should display "No results found" message when API returns empty list', () => {
    cy.intercept('GET', searchEndpoint, {
      statusCode: 200,
      body: {
        results: [],
        total: 0
      }
    }).as('emptySearch');

    cy.get('[data-testid="search-input"]').type('nonexistent query');
    cy.get('[data-testid="search-button"]').click();

    cy.wait('@emptySearch');

    cy.get('[data-testid="no-results-message"]')
      .should('be.visible')
      .and('contain', 'No results found');

    cy.get('[data-testid="results-list"]').should('not.exist');
  });

  it('should display "No results found" message when API returns null results', () => {
    cy.intercept('GET', searchEndpoint, {
      statusCode: 200,
      body: {
        results: null,
        total: 0
      }
    }).as('nullSearch');

    cy.get('[data-testid="search-input"]').type('another query');
    cy.get('[data-testid="search-button"]').click();

    cy.wait('@nullSearch');

    cy.get('[data-testid="no-results-message"]')
      .should('be.visible')
      .and('contain', 'No results found');
  });

  it('should hide "No results found" message when results are returned', () => {
    cy.intercept('GET', searchEndpoint, {
      statusCode: 200,
      body: {
        results: [
          { id: 1, title: 'Result 1' },
          { id: 2, title: 'Result 2' }
        ],
        total: 2
      }
    }).as('successSearch');

    cy.get('[data-testid="search-input"]').type('valid query');
    cy.get('[data-testid="search-button"]').click();

    cy.wait('@successSearch');

    cy.get('[data-testid="no-results-message"]').should('not.exist');
    cy.get('[data-testid="results-list"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length', 2);
  });

  it('should display "No results found" message when API returns error status', () => {
    cy.intercept('GET', searchEndpoint, {
      statusCode: 500,
      body: {
        error: 'Internal Server Error'
      }
    }).as('errorSearch');

    cy.get('[data-testid="search-input"]').type('error query');
    cy.get('[data-testid="search-button"]').click();

    cy.wait('@errorSearch');

    cy.get('[data-testid="no-results-message"]')
      .should('be.visible')
      .and('contain', 'No results found');
  });

  it('should handle empty string results gracefully', () => {
    cy.intercept('GET', searchEndpoint, {
      statusCode: 200,
      body: {
        results: ['', '', ''],
        total: 3
      }
    }).as('emptyStringSearch');

    cy.get('[data-testid="search-input"]').type('empty strings');
    cy.get('[data-testid="search-button"]').click();

    cy.wait('@emptyStringSearch');

    cy.get('[data-testid="no-results-message"]')
      .should('be.visible')
      .and('contain', 'No results found');
  });
});
